/// <summary>
/// This is an extension class for PurchLineOpenOrder form.
/// </summary>
[ExtensionOf(FormStr(PurchLineOpenOrder))]
final class METPurchLineOpenOrderForm_Extension
{
}

Method.Source:
    /// <summary>
    /// Initializing the form controls visibility.
    /// </summary>
    public void  init()
    {
        next init();

        FormRun formRun = this;

        if (formRun.args().menuItemName() == menuItemDisplayStr(METPurchTableListPage))
        {
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, InventoryDimensions)).visible(false);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, PurchLine_RemainBackPurchPhysical)).visible(false);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, PurchLine_PurchQty)).visible(false);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, PurchLine_PdsCWRemainInventPhysical)).visible(false);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, PurchLine_PdsCWQty)).visible(false);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, ITMStatusId)).visible(false);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, InventDim_InventSiteId)).visible(true);
            formRun.design(1).controlName(FormControlStr(PurchLineOpenOrder, InventDim_InventLocationId)).visible(true);
            FormDataSource  purchLine_ds = formRun.dataSource(formDataSourceStr(PurchLineOpenOrder,PurchLine));
            purchLine_ds.object(fieldnum(PurchLine, VendAccount)).visible(true);
        }
    }
